import itertools

def dot(a, b): return sum(x*y for x, y in zip(a, b))
def cross(a, b): return (a[1]*b[2]-a[2]*b[1], a[2]*b[0]-a[0]*b[2], a[0]*b[1]-a[1]*b[0])
def par(a, b): return cross(a, b) == (0, 0, 0)
def nz(a): return any(a)

R = range(-2, 3)
vecs = [v for v in itertools.product(R, repeat=3) if nz(v)]

def find_counter(name, gen):
    cnt = 0
    ce = None
    for case in gen:
        cnt += 1
        if ce is None:
            ce = case
    return cnt, ce

# A: alpha ⟂ beta, l = alpha∩beta, m ⟂ l; conclusion m ⟂ beta (d ∥ nb).
# Planes alpha, beta are non-parallel (they intersect in l).
def genA():
    for na in vecs:
        for nb in vecs:
            if dot(na, nb) == 0:
                l = cross(na, nb)
                for d in vecs:
                    if dot(d, l) == 0 and not par(d, nb):
                        yield (na, nb, d)

# B: alpha∩gamma = m, alpha ⟂ gamma, beta ⟂ gamma; m ⟂ beta needs d ∥ nb.
def genB():
    for na in vecs:
        for ng in vecs:
            if dot(na, ng) == 0:
                d = cross(na, ng)
                for nb in vecs:
                    if dot(nb, ng) == 0 and not par(nb, na) and not par(nb, ng) and not par(d, nb):
                        yield (na, ng, nb, d)

# C: alpha ⟂ gamma, beta ⟂ gamma, m ⟂ alpha; need d ∥ nb.
def genC():
    for na in vecs:
        for ng in vecs:
            if dot(na, ng) == 0:
                for nb in vecs:
                    if dot(nb, ng) == 0 and not par(nb, ng):
                        d = na
                        if not par(d, nb):
                            yield (na, ng, nb, d)

# D: n ⟂ alpha, n ⟂ beta, m ⟂ alpha; check all cases satisfy d ∥ nb.
def genD_all():
    tot = 0; bad = 0
    for n in vecs:
        for na in vecs:
            if not par(n, na): continue
            for nb in vecs:
                if not par(n, nb): continue
                for d in vecs:
                    if par(d, na):
                        tot += 1
                        if not par(d, nb):
                            bad += 1
    return tot, bad

for name, g in (("A", genA()), ("B", genB()), ("C", genC())):
    c, ce = find_counter(name, g)
    print(name, "counterexamples found:", c, "example:", ce)

tot, bad = genD_all()
print("D cases checked (exhaustive over small integer range):", tot, "violations:", bad)

ok = True
for name, g in (("A", genA()), ("B", genB()), ("C", genC())):
