    if c == 0: ok = False
if bad != 0: ok = False
print("CHECK PASS" if ok else "CHECK FAIL")
print("Note: D verified exhaustively over a bounded grid, plus it follows from parallel normals; A, B, C refuted by explicit counterexamples.")
